package com.adesa.attendance.vendor;
import static com.adesa.attendance.vendor.VendorRules.*;
import com.fasterxml.jackson.databind.ObjectMapper;import com.fasterxml.jackson.core.type.TypeReference;
import java.time.*;import java.util.*;import java.nio.charset.StandardCharsets;
import org.springframework.beans.factory.annotation.Value;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;

@Service @Transactional
public class VendorService {
 private final JdbcTemplate db;private final ObjectMapper json;private final VendorCrypto crypto;private final boolean enabled,demo;private final Map<String,String> pages;private final String staffUrl;
 public VendorService(JdbcTemplate db,ObjectMapper json,VendorCrypto crypto,@Value("${vendor.enabled:false}")boolean enabled,@Value("${vendor.demo:false}")boolean demo,@Value("${vendor.registration-pages:}")String configured,@Value("${adesa.account.public-url:http://localhost:5180}")String staffUrl){this.db=db;this.json=json;this.crypto=crypto;this.enabled=enabled;this.demo=demo;this.staffUrl=staffUrl;try{pages=configured.isBlank()?Map.of("HOLDINGS","https://adesahq.com/vendors/register","ENERGY","https://adesaenergy.com/vendors/register","MEDIA","https://adesamedia.com/vendors/register","SERVICES","https://adesahq.com/vendors/services/register","DISTRIBUTION","https://adesahq.com/vendors/distribution/register"):json.readValue(configured,new TypeReference<Map<String,String>>(){});for(String code:SITES){String page=pages.getOrDefault(code,"");check(page.matches("https://[^\\s#?]+")||demo&&page.matches("http://(localhost|127\\.0\\.0\\.1):[0-9]+/[^\\s#?]+"),"Configure verified HTTPS vendor registration pages.");}}catch(Exception e){throw new IllegalStateException("Invalid vendor registration page configuration");}}
 public JdbcTemplate jdbc(){return db;}
 public VendorCrypto crypt(){return crypto;}
 public boolean isDemo(){return demo;}
 public void available(){if(!enabled||!crypto.configured())throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Vendor registration is not enabled.");}
 public void context(String key,String value){db.queryForObject("select set_config(?,?,true)",String.class,"vendor."+key,value);}
 public String encode(Object data){try{return json.writeValueAsString(data);}catch(Exception e){throw new IllegalStateException(e);}}
 public Map<String,Object> object(String data){try{return json.readValue(data,new TypeReference<LinkedHashMap<String,Object>>(){});}catch(Exception e){throw new IllegalStateException("Private vendor record could not be read");}}
 public byte[] pack(Object data,String purpose){return crypto.seal(encode(data).getBytes(StandardCharsets.UTF_8),purpose);}
 public Map<String,Object> unpack(byte[] data,String purpose){return object(new String(crypto.open(data,purpose),StandardCharsets.UTF_8));}
 public Map<String,Object> one(String sql,Object...values){var rows=db.queryForList(sql,values);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Vendor record or link not found.");return rows.getFirst();}
 public static Instant instant(Object value){return value instanceof java.sql.Timestamp t?t.toInstant():value instanceof OffsetDateTime d?d.toInstant():Instant.parse(value.toString());}
 public void rate(String key,int limit){int hits=db.queryForObject("insert into vendor_private.rate values(?,?,1) on conflict(key_hash,bucket) do update set hits=vendor_private.rate.hits+1 returning hits",Integer.class,crypto.hash(key),Instant.now().getEpochSecond()/60);if(hits>limit)throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Please wait a minute before trying again.");}
 private void validLink(Map<String,Object> link){check(Boolean.TRUE.equals(link.get("active"))&&link.get("revoked_at")==null&&(link.get("expires_at")==null||Instant.now().isBefore(instant(link.get("expires_at")))),"This registration link is inactive, revoked or expired.");check(!"INVITATION".equals(link.get("kind"))||((Number)link.get("uses")).intValue()==0,"This individual invitation has already been used.");}
 public Map<String,Object> open(String token,String subsidiary,boolean correction){available();check(SITES.contains(subsidiary),"Unknown subsidiary.");UUID id=UUID.randomUUID();String credential=crypto.token();Map<String,Object> origin;
 if(correction){origin=one("select * from vendor_private.request where token_hash=? for update",crypto.hash(token));context("application",origin.get("application_id").toString());origin.put("subsidiary",one("select subsidiary from vendor_private.application where id=?",origin.get("application_id")).get("subsidiary"));}else origin=one("select * from vendor_private.link where token_hash=? for update",crypto.hash(token));
 // The correction lookup below uses only a request token; set its verified app context before reading protected data.
 if(correction){check(origin.get("consumed_at")==null&&Instant.now().isBefore(instant(origin.get("expires_at"))),"This information request has expired or was already completed.");}else validLink(origin);
 check(subsidiary.equals(origin.get("subsidiary")),"This invitation belongs to another ADESA registration page.");
 db.update("insert into vendor_private.session(id,link_id,request_id,subsidiary,token_hash,expires_at,application_id) values(?,?,?,?,?,?,?)",id,correction?null:origin.get("id"),correction?origin.get("id"):null,subsidiary,crypto.hash(credential),java.sql.Timestamp.from(Instant.now().plus(Duration.ofHours(24))),correction?origin.get("application_id"):null);
 return Map.of("session",credential,"context",sessionView(id));}
 private Map<String,Object> authenticate(String token,String site){available();var s=one("select * from vendor_private.session where token_hash=? and expires_at>now() for update",crypto.hash(token==null?"":token));check(site.equals(s.get("subsidiary")),"This session belongs to another subsidiary.");context("session",s.get("id").toString());if(s.get("application_id")!=null)context("application",s.get("application_id").toString());
 if(!Boolean.TRUE.equals(s.get("submitted"))){if(s.get("link_id")!=null)validLink(one("select * from vendor_private.link where id=? for update",s.get("link_id")));else{var r=one("select * from vendor_private.request where id=? for update",s.get("request_id"));check(r.get("consumed_at")==null&&Instant.now().isBefore(instant(r.get("expires_at"))),"This information request is no longer valid.");}}return s;}
 public Map<String,Object> state(String token,String site){var s=authenticate(token,site);return sessionView((UUID)s.get("id"));}
 private Map<String,Object> sessionView(UUID id){var s=one("select * from vendor_private.session where id=?",id);context("session",id.toString());var out=new LinkedHashMap<String,Object>();out.put("subsidiary",s.get("subsidiary"));out.put("subsidiaryName",label(String.valueOf(s.get("subsidiary"))));out.put("demo",demo);out.put("formVersion",VERSION);out.put("privacy",PRIVACY);out.put("declaration",DECLARATION);out.put("consent",CONSENT);out.put("conflictQuestion",CONFLICT);out.put("categories",CATEGORIES);out.put("documentCategories",DOCS);out.put("submitted",s.get("submitted"));
 if(s.get("application_id")!=null){context("application",s.get("application_id").toString());if(Boolean.TRUE.equals(s.get("submitted")))out.put("receipt",receipt((UUID)s.get("application_id")));else{var app=one("select * from vendor_private.application where id=?",s.get("application_id"));var revision=revision((UUID)app.get("id"),((Number)app.get("current_revision")).intValue());out.put("prefill",unpack((byte[])revision.get("payload_cipher"),"revision:"+revision.get("id")));var request=one("select * from vendor_private.request where id=?",s.get("request_id"));out.put("request",new String(crypto.open((byte[])request.get("message_cipher"),"request:"+request.get("id")),StandardCharsets.UTF_8));}}
 out.put("documents",documentsForSession(id));return out;}
 public Map<String,Object> revision(UUID app,int number){return one("select * from vendor_private.revision where application_id=? and number=?",app,number);}
 private java.util.List<Map<String,Object>> documentsForSession(UUID session){return db.queryForList("select id,category,filename,mime_type,expected_size,ready,created_at from vendor_private.document where session_id=? order by created_at",session);}
 public Map<String,Object> uploadStart(String token,String site,Map<String,Object> input){var s=authenticate(token,site);check(!Boolean.TRUE.equals(s.get("submitted")),"This signed application is already submitted.");String category=text(input.get("category"),40),filename=text(input.get("filename"),180),mime=text(input.get("mime"),60);check(category.equals("SIGNATURE")||DOCS.contains(category),"Select a document category.");check(!filename.isBlank()&&!filename.contains("/")&&!filename.contains("\\")&&!filename.contains("\r")&&!filename.contains("\n"),"Use a valid filename.");check(input.get("size") instanceof Number,"Choose a file.");int size=((Number)input.get("size")).intValue();check(size>0&&size<=(category.equals("SIGNATURE")?2:10)*1024*1024,"The file exceeds its allowed size.");int count=db.queryForObject("select count(*) from vendor_private.document where session_id=? and category<>'SIGNATURE'",Integer.class,s.get("id"));check(category.equals("SIGNATURE")||count<10,"Upload at most ten supporting files.");if(category.equals("SIGNATURE"))check(db.queryForObject("select count(*) from vendor_private.document where session_id=? and category='SIGNATURE'",Integer.class,s.get("id"))<1,"Remove the existing signature before replacing it.");UUID id=UUID.randomUUID();db.update("insert into vendor_private.document(id,session_id,category,filename,declared_type,expected_size,body_cipher) values(?,?,?,?,?,?,?)",id,s.get("id"),category,filename,mime,size,crypto.seal(new byte[0],"document:"+id));return Map.of("id",id);}
 public Map<String,Object> chunk(String token,String site,UUID id,Map<String,Object> input){var s=authenticate(token,site);check(!Boolean.TRUE.equals(s.get("submitted")),"The signed application cannot be changed.");var d=one("select * from vendor_private.document where id=? and session_id=? for update",id,s.get("id"));check(!Boolean.TRUE.equals(d.get("ready"))&&d.get("application_id")==null,"This document is already finalised.");check(input.get("index") instanceof Number&&((Number)input.get("index")).intValue()==((Number)d.get("chunks")).intValue(),"Resume upload from the last confirmed chunk.");byte[] part;try{part=Base64.getDecoder().decode(text(input.get("data"),710000));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid file chunk.");}check(part.length>0&&part.length<=512*1024,"File chunks must be at most 512 KB.");byte[] old=crypto.open((byte[])d.get("body_cipher"),"document:"+id);check(old.length+part.length<=((Number)d.get("expected_size")).intValue(),"File data exceeds the declared size.");byte[] all=Arrays.copyOf(old,old.length+part.length);System.arraycopy(part,0,all,old.length,part.length);db.update("update vendor_private.document set body_cipher=?,received_size=?,chunks=chunks+1 where id=?",crypto.seal(all,"document:"+id),all.length,id);return Map.of("received",all.length,"nextIndex",((Number)d.get("chunks")).intValue()+1);}
 public Map<String,Object> finalizeUpload(String token,String site,UUID id){var s=authenticate(token,site);check(!Boolean.TRUE.equals(s.get("submitted")),"This application is submitted.");var d=one("select * from vendor_private.document where id=? and session_id=? for update",id,s.get("id"));if(Boolean.TRUE.equals(d.get("ready")))return Map.of("id",id,"ready",true);check(d.get("received_size").equals(d.get("expected_size")),"Finish uploading every file chunk.");byte[] body=crypto.open((byte[])d.get("body_cipher"),"document:"+id);var file=VendorFiles.validate(body,String.valueOf(d.get("filename")),"SIGNATURE".equals(d.get("category")));db.update("update vendor_private.document set ready=true,mime_type=?,content_hash=? where id=?",file.mime(),crypto.hash(Base64.getEncoder().encodeToString(body)),id);return Map.of("id",id,"ready",true,"mime",file.mime());}
 public void removeUpload(String token,String site,UUID id){var s=authenticate(token,site);check(!Boolean.TRUE.equals(s.get("submitted")),"Submitted documents are immutable.");db.update("delete from vendor_private.document where id=? and session_id=? and application_id is null",id,s.get("id"));}
 private Map<String,Object> receipt(UUID app){var a=one("select * from vendor_private.application where id=?",app);var r=revision(app,((Number)a.get("current_revision")).intValue());var data=unpack((byte[])r.get("payload_cipher"),"revision:"+r.get("id"));return Map.of("reference",a.get("reference"),"businessName",data.get("businessName"),"subsidiary",label(String.valueOf(a.get("subsidiary"))),"submittedAt",r.get("submitted_at"),"status",a.get("status"));}
 public Map<String,Object> submit(String token,String site,Map<String,Object> raw){var s=authenticate(token,site);if(Boolean.TRUE.equals(s.get("submitted")))return receipt((UUID)s.get("application_id"));var data=validate(raw);if(demo)check(String.valueOf(data.get("contactEmail")).endsWith(".test"),"Use a fictional .test email address in this demonstration.");
 if(s.get("link_id")!=null){var link=one("select * from vendor_private.link where id=? for update",s.get("link_id"));validLink(link);if(link.get("invited_email_hash")!=null)check(link.get("invited_email_hash").equals(crypto.fingerprint(String.valueOf(data.get("contactEmail")))),"Use the email address named in this invitation.");}
 UUID app=s.get("application_id")==null?UUID.randomUUID():(UUID)s.get("application_id");context("application",app.toString());boolean amendment=s.get("request_id")!=null;int number=1;Map<String,Object> previous=null;
 if(amendment){var a=one("select * from vendor_private.application where id=? for update",app);number=((Number)a.get("current_revision")).intValue()+1;var old=revision(app,number-1);previous=unpack((byte[])old.get("payload_cipher"),"revision:"+old.get("id"));}
 var fingerprints=new LinkedHashMap<String,String>();for(String field:List.of("businessName","cac","tin","contactEmail","contactPhone")){String value=String.valueOf(data.get(field));if(!value.isBlank())fingerprints.put(field,crypto.fingerprint(field+":"+normal(value)));}
 var duplicateIds=new LinkedHashSet<UUID>();for(var entry:fingerprints.entrySet())for(var row:db.queryForList("select application_id from vendor_private.duplicate_index where kind=? and fingerprint=? and application_id<>?",entry.getKey(),entry.getValue(),app))duplicateIds.add((UUID)row.get("application_id"));
 if(!amendment){String business=fingerprints.get("businessName"),mail=fingerprints.get("contactEmail");int same=db.queryForObject("select count(*) from vendor_private.duplicate_index a join vendor_private.duplicate_index b on b.application_id=a.application_id join vendor_private.session v on v.application_id=a.application_id where a.kind='businessName' and a.fingerprint=? and b.kind='contactEmail' and b.fingerprint=? and v.subsidiary=?",Integer.class,business,mail,site);if(same>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"This business and contact email already have an application for this subsidiary. Contact the administrator for corrections.");}
 var docs=db.queryForList("select * from vendor_private.document where session_id=? order by created_at",s.get("id"));check(docs.stream().allMatch(d->Boolean.TRUE.equals(d.get("ready"))),"Finish or remove incomplete uploads before submitting.");check(docs.stream().filter(d->!"SIGNATURE".equals(d.get("category"))).count()<=10,"At most ten supporting documents are allowed.");UUID signature;
 if("TYPED".equals(data.get("signatureMethod"))){db.update("delete from vendor_private.document where session_id=? and category='SIGNATURE' and application_id is null",s.get("id"));byte[] image=VendorFiles.signature(String.valueOf(data.get("signatoryName")),String.valueOf(data.get("signatureStyle")));signature=UUID.randomUUID();db.update("insert into vendor_private.document(id,session_id,category,filename,declared_type,mime_type,expected_size,received_size,body_cipher,content_hash,ready) values(?,?,'SIGNATURE','generated-signature.png','image/png','image/png',?,?,?,?,true)",signature,s.get("id"),image.length,image.length,crypto.seal(image,"document:"+signature),crypto.hash(Base64.getEncoder().encodeToString(image)));}
 else{signature=docs.stream().filter(d->"SIGNATURE".equals(d.get("category"))).map(d->(UUID)d.get("id")).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Upload a signature image."));}
 String reference="VND-"+site.substring(0,3)+"-"+UUID.randomUUID().toString().replace("-","").substring(0,12).toUpperCase(Locale.ROOT);boolean hasBank=!String.valueOf(data.get("accountNumber")).isBlank();
 if(!amendment){db.update("insert into vendor_private.application(id,reference,subsidiary,link_id,entity_id,banking_status,conflict,categories,duplicate_ids) values(?,?,?,?,?,?,?,?::text[],?::uuid[])",app,reference,site,s.get("link_id"),UUID.randomUUID(),hasBank?"UNVERIFIED":"NOT_PROVIDED","Yes".equals(data.get("conflict")),array((List<?>)data.get("categories")),array(new ArrayList<>(duplicateIds)));}
 else{final Map<String,Object> prior=previous;boolean changed=List.of("bankName","accountName","accountNumber","bankFormat").stream().anyMatch(k->!Objects.equals(data.get(k),previousData(prior,k)));db.update("update vendor_private.application set status='UNDER_REVIEW',current_revision=?,categories=?::text[],conflict=?,banking_status=case when ? then ? else banking_status end,banking_verified_by=case when ? then null else banking_verified_by end,banking_verified_at=case when ? then null else banking_verified_at end,updated_at=now() where id=?",number,array((List<?>)data.get("categories")),"Yes".equals(data.get("conflict")),changed,hasBank?"UNVERIFIED":"NOT_PROVIDED",changed,changed,app);db.update("update vendor_private.request set consumed_at=now() where id=?",s.get("request_id"));}
 UUID revision=UUID.randomUUID();data.put("applicationReference",amendment?one("select reference from vendor_private.application where id=?",app).get("reference"):reference);data.put("subsidiary",site);data.put("signatureId",signature);data.put("submissionTime",Instant.now().toString());
 db.update("insert into vendor_private.revision(id,application_id,session_id,number,payload_cipher,signature_id,content_hash,form_version) values(?,?,?,?,?,?,?,?)",revision,app,s.get("id"),number,pack(data,"revision:"+revision),signature,crypto.hash(encode(data)),VERSION);
 db.update("update vendor_private.document set application_id=? where session_id=? and application_id is null",app,s.get("id"));db.update("update vendor_private.session set submitted=true,application_id=? where id=?",app,s.get("id"));if(!amendment)db.update("update vendor_private.link set uses=uses+1 where id=?",s.get("link_id"));for(var entry:fingerprints.entrySet())db.update("insert into vendor_private.duplicate_index values(?,?,?) on conflict(application_id,kind) do update set fingerprint=excluded.fingerprint",app,entry.getKey(),entry.getValue());
 context("access","WORKFLOW");audit(app,"vendor-session:"+s.get("id"),amendment?"SIGNED_AMENDMENT":"SUBMITTED",Map.of("revision",number,"conflictDeclared",data.get("conflict"),"possibleDuplicates",duplicateIds.size()));
 String ref=String.valueOf(data.get("applicationReference"));queue(app,String.valueOf(data.get("contactEmail")),"ADESA vendor application received", "Thank you for registering your business with ADESA. Your vendor acquisition application has been successfully received and will be reviewed. You will be contacted if additional information is required.\nApplication reference: "+ref+"\nBusiness: "+data.get("businessName")+"\nSubsidiary: "+label(site)+"\nSubmission does not constitute vendor approval.",false);
 notifyAdmins(app,amendment?"ADDITIONAL_INFORMATION":"NEW_APPLICATION",ref);if("Yes".equals(data.get("conflict")))notifyAdmins(app,"CONFLICT_DECLARED",ref);if(hasBank)notifyAdmins(app,"BANKING_SUBMITTED",ref);if(amendment&&docs.size()>0)notifyAdmins(app,"REQUESTED_DOCUMENTS",ref);
 return receipt(app);}
 private static Object previousData(Map<String,Object> data,String key){return data==null?null:data.get(key);}
 public static String array(List<?> values){return "{"+String.join(",",values.stream().map(v->"\""+v.toString().replace("\\","\\\\").replace("\"","\\\"")+"\"").toList())+"}";}
 public void audit(UUID app,String actor,String action,Object detail){db.update("insert into vendor_private.audit(application_id,actor,action,detail_cipher) values(?,?,?,?)",app,actor,action,pack(detail,"audit:"+action));}
 public void queue(UUID app,String recipient,String subject,String body,boolean internal){UUID id=UUID.randomUUID();db.update("insert into vendor_private.outbox(id,application_id,recipient_cipher,body_cipher,subject,internal) values(?,?,?,?,?,?)",id,app,crypto.seal(recipient.getBytes(StandardCharsets.UTF_8),"recipient:"+id),crypto.seal(body.getBytes(StandardCharsets.UTF_8),"outbox:"+id),subject,internal);}
 public void notifyAdmins(UUID app,String kind,String reference){for(var a:db.queryForList("select id,email from employees where role='ADMIN' and is_active")){db.update("insert into vendor_private.notice(id,application_id,recipient_id,kind) values(?,?,?,?)",UUID.randomUUID(),app,a.get("id"),kind);queue(app,String.valueOf(a.get("email")),"ADESA Vendor Management: "+kind.replace('_',' '),"Vendor application "+reference+" requires administrator attention.\nOpen the administrator-only application: "+staffUrl+"/vendors?application="+app+"\nBanking details, signatures and documents are available only after administrator authentication.",true);}}
 public String page(String site){return pages.get(site);}
 public java.util.List<Map<String,Object>> sites(){return SITES.stream().map(code->Map.<String,Object>of("code",code,"name",label(code),"page",pages.get(code))).toList();}
}
